    estimatedMin: 12,
    datamartId: 'consumer',
    prompt: 'The growth team wants to segment all users into four engagement quartiles based on total interaction count — quartile 1 = least engaged, quartile 4 = most engaged. Include users with zero interactions. Return user_id, username, interaction_count, and quartile, ordered by interaction_count ascending, then user_id.',
