    solution: 'SELECT txn_id, account_id, amount, occurred_at,\n       FIRST_VALUE(amount) OVER (PARTITION BY account_id ORDER BY occurred_at) AS first_txn_amount\nFROM transactions\nORDER BY account_id, occurred_at',
