    datamartId: 'consumer',
    prompt: 'The algorithm team uses diversity of engagement actions as a quality signal — content that attracts views, likes, saves, and comments is healthier than content that only gets views. For each content piece, return content id, content type, category, and the number of distinct interaction action types it received.',
    expectedColumns: ['content_id', 'content_type', 'category', 'unique_actions'],
