    hints: ['JOIN providers to appointments on provider_id. Then GROUP BY provider_id, name, specialty and use SUM(CASE WHEN no_show = 0 THEN 1 ELSE 0 END) for completed and SUM(no_show) for no_shows. Use 100.0 * completed / total to avoid integer division.'],
