    isFree: false,
    tags: ['forensic', 'GROUP BY', 'segmentation', 'wrong dimension', 'bug-fix'],
    roles: ['PA', 'DA', 'PM'],
    priority: 2,
    estimatedMin: 6,
    datamartId: 'consumer',
    prompt: 'The revenue team wants premium conversion rates by device platform (iOS / Android / web) to decide where to invest in premium feature development. The report has been running for 6 weeks. A PM reviewing the deck noticed the report shows 6 rows, not 3. Find the bug.',
    brokenQuery: 'SELECT country,\n  COUNT(*) AS total_users,\n  SUM(is_premium) AS premium_users,\n  ROUND(100.0 * SUM(is_premium) / COUNT(*), 1) AS premium_pct\nFROM users\nGROUP BY country\nORDER BY premium_pct DESC',
    brokenOutputNote: 'Groups by country (6 rows: AU, CA, DE, GB, IN, US) instead of device_os (3 rows: ios, android, web). Returns a geographic breakdown when the question was about platforms. The SELECT and GROUP BY use the wrong column.',
    expectedColumns: ['device_os', 'total_users', 'premium_users', 'premium_pct'],
